<div class="inquiry-detail-layout"><section class="panel"><div class="panel-heading"><h2><?= e($row['reference']) ?></h2><a class="btn" href="<?= e(url($returnTo)) ?>">← Inquiry inbox</a></div><div class="record-contact-actions"><a class="btn" href="<?= e('mailto:'.$row['email'].'?subject='.rawurlencode('Re: '.$row['reference'])) ?>">Open email app ↗</a><?php if($row['phone']&&preg_match('/[0-9]/',$row['phone'])): ?><a class="btn" href="tel:<?= e(preg_replace('/[^+0-9]/','',$row['phone'])) ?>">Call contact</a><?php endif; ?></div><p class="form-note">Replies are sent through your email or phone app. This website does not send email automatically.</p><dl class="inquiry-record"><?php foreach(['kind','full_name','company_name','country','email','phone','business_type','categories','volume','network','message','batch_number','created_at'] as $key): if($row[$key]==='')continue; ?><div><dt><strong><?= e(ucwords(str_replace('_',' ',$key))) ?></strong></dt><dd><?= nl2br(e($row[$key])) ?></dd></div><?php endforeach; ?></dl></section>
<aside class="panel"><span class="eyebrow">STAFF WORKSPACE</span><h2>Handling & follow-up</h2><form method="post" action="<?= url('admin/inquiries/'.$row['id'].'/status') ?>"><?= csrf_field() ?><input type="hidden" name="return_to" value="<?= e($returnTo) ?>"><div class="field"><label for="status">Handling status</label><select name="status" id="status"><?php foreach(['new'=>'New','in_progress'=>'In progress','resolved'=>'Resolved'] as $value=>$label): ?><option value="<?= $value ?>" <?= field_value($row,'status')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="field"><label for="internal_notes">Internal follow-up notes</label><textarea name="internal_notes" id="internal_notes" rows="7" maxlength="10000"><?= e(field_value($row,'internal_notes')) ?></textarea><small>Visible only to signed-in staff. Notes are not sent to the customer.</small></div><?php if($row['updated_at']): ?><p class="form-note">Last handled <?= e($row['updated_at']) ?><br><?= e($row['handler_email']??'Administrator') ?></p><?php endif; ?><div class="form-actions"><button class="btn btn-primary">Save handling details</button></div></form>
<form class="delete-form" data-name="<?= e($row['reference']) ?>" method="post" action="<?= url('admin/inquiries/'.$row['id'].'/delete') ?>"><?= csrf_field() ?><input type="hidden" name="return_to" value="<?= e($returnTo) ?>"><button class="btn danger-text">Delete inquiry permanently</button></form></aside></div>